<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Manage Test Marks</h1><p>Select a class, then create a test for its assigned subject and students.</p></div></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Class</label><select class="module-select" name="class" required><option value="">Select Class</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Load Class</button></form><?php if($selectedClass):?><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/class-tests/marks') ?>"><?= csrf_field() ?><input type="hidden" name="class" value="<?= $selectedClass ?>"><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Subject</label><select class="module-select" name="subject" required><?php foreach($subjects as$s):?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Date</label><input class="module-input" type="date" name="date" value="<?= date('Y-m-d') ?>" required></div><div class="module-field"><label>Title</label><input class="module-input" name="title" required></div><div class="module-field"><label>Maximum Marks</label><input class="module-input" type="number" name="total_marks" min="1" step="0.01" required></div></div><table class="data-table"><thead><tr><th>Registration</th><th>Student</th><th>Marks</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td><td><input class="module-input" type="number" min="0" step="0.01" name="marks[<?= $s['id'] ?>]" required></td></tr><?php endforeach ?></tbody></table><button class="btn btn--primary" <?= !$students||!$subjects?'disabled':'' ?>>Save Test Marks</button></form></div></section><?php endif ?></div></div></main>
